00118     public static function formatWindowsPath($path)
00119     {
00120         if (empty($path)) {
00121             return $path;
00122         }
00123 
00124         $cacheKey = 'w_' . $path;
00125         if (isset(self::$pathFormatCache[$cacheKey])) {
00126             self::$pathFormatStats['windows_hits']++;
00127             return self::$pathFormatCache[$cacheKey];
00128         }
00129 
00130         self::$pathFormatStats['windows_misses']++;
00131 
00132         $result = str_replace('/', '\\', $path);
00133 
00134         if (count(self::$pathFormatCache) < self::$pathFormatCacheMaxSize) {
00135             self::$pathFormatCache[$cacheKey] = $result;
00136         } else {
00137             $removeCount = (int)(self::$pathFormatCacheMaxSize * 0.1);
00138             self::$pathFormatCache = array_slice(self::$pathFormatCache, $removeCount, null, true);
00139             self::$pathFormatCache[$cacheKey] = $result;
00140         }
00141 
00142         return $result;
00143     }
00144 
