00201     public static function changePath($filesToScan, $rootPath = null)
00202     {
00203         global $bearsamppRoot, $bearsamppCore;
00204 
00205         $result = array(
00206             'countChangedOcc'   => 0,
00207             'countChangedFiles' => 0
00208         );
00209 
00210         $rootPath           = $rootPath != null ? $rootPath : Path::getRootPath();
00211         $unixOldPath        = Path::formatUnixPath($bearsamppCore->getLastPathContent());
00212         $windowsOldPath     = Path::formatWindowsPath($bearsamppCore->getLastPathContent());
00213         $unixCurrentPath    = Path::formatUnixPath($rootPath);
00214         $windowsCurrentPath = Path::formatWindowsPath($rootPath);
00215 
00216         foreach ($filesToScan as $fileToScan) {
00217             $tmpCountChangedOcc = 0;
00218             $fileContentOr      = file_get_contents($fileToScan);
00219 
00220             if ($fileContentOr === false) {
00221                 Log::error("changePath(): Failed to read file: " . $fileToScan);
00222                 continue;
00223             }
00224 
00225             $fileContent = $fileContentOr;
00226 
00227             // old path
00228             if (stripos($fileContent, $unixOldPath) !== false) {
00229                 $fileContent        = str_ireplace($unixOldPath, $unixCurrentPath, $fileContent, $countChanged);
00230                 $tmpCountChangedOcc += $countChanged;
00231             }
00232             if (stripos($fileContent, $windowsOldPath) !== false) {
00233                 $fileContent        = str_ireplace($windowsOldPath, $windowsCurrentPath, $fileContent, $countChanged);
00234                 $tmpCountChangedOcc += $countChanged;
00235             }
00236 
00237             // placeholders
00238             if (strpos($fileContent, Core::PATH_LIN_PLACEHOLDER) !== false) {
00239                 $fileContent        = str_replace(Core::PATH_LIN_PLACEHOLDER, $unixCurrentPath, $fileContent, $countChanged);
00240                 $tmpCountChangedOcc += $countChanged;
00241             }
00242             if (strpos($fileContent, Core::PATH_WIN_PLACEHOLDER) !== false) {
00243                 $fileContent        = str_replace(Core::PATH_WIN_PLACEHOLDER, $windowsCurrentPath, $fileContent, $countChanged);
00244                 $tmpCountChangedOcc += $countChanged;
00245             }
00246 
00247             if ($fileContentOr != $fileContent) {
00248                 if (file_put_contents($fileToScan, $fileContent) !== false) {
00249                     $result['countChangedOcc']   += $tmpCountChangedOcc;
00250                     $result['countChangedFiles'] += 1;
00251                 } else {
00252                     Log::error("changePath(): Failed to write to file: " . $fileToScan);
00253                 }
00254             }
00255         }
00256 
00257         Log::debug('changePath() completed: ' . $result['countChangedFiles'] . ' files changed, ' . $result['countChangedOcc'] . ' total occurrences');
00258 
00259         return $result;
00260     }
