00407     public static function getLocalUrl($request = null)
00408     {
00409         global $bearsamppBins;
00410         $isHttps = (isset($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off');
00411         $scheme = $isHttps ? 'https://' : 'http://';
00412         $host = (isset($_SERVER['SERVER_NAME'])) ? $_SERVER['SERVER_NAME'] : 'localhost';
00413         
00414         $port = 80;
00415         if (isset($bearsamppBins) && $bearsamppBins->getApache() !== null) {
00416             $port = $isHttps ? $bearsamppBins->getApache()->getSslPort() : $bearsamppBins->getApache()->getPort();
00417         }
00418 
00419         $portSuffix = '';
00420         if ($isHttps) {
00421             if ($port != 443) {
00422                 $portSuffix = ':' . $port;
00423             }
00424         } else {
00425             if ($port != 80) {
00426                 $portSuffix = ':' . $port;
00427             }
00428         }
00429 
00430         return $scheme . $host . $portSuffix . (!empty($request) ? '/' . $request : '');
00431     }
