00658     public static function getNssmEnvPaths()
00659     {
00660         global $bearsamppBins, $bearsamppTools;
00661 
00662         $paths = '';
00663 
00664         // Add paths for enabled bins
00665         if (isset($bearsamppBins)) {
00666             if ($bearsamppBins->getApache() && $bearsamppBins->getApache()->isEnable()) {
00667                 $paths .= self::getModuleSymlinkPath($bearsamppBins->getApache()) . '/bin;';
00668             }
00669             if ($bearsamppBins->getPhp() && $bearsamppBins->getPhp()->isEnable()) {
00670                 $paths .= self::getModuleSymlinkPath($bearsamppBins->getPhp()) . ';';
00671                 $paths .= self::getModuleSymlinkPath($bearsamppBins->getPhp()) . '/pear;';
00672                 $paths .= self::getModuleSymlinkPath($bearsamppBins->getPhp()) . '/deps;';
00673                 $paths .= self::getModuleSymlinkPath($bearsamppBins->getPhp()) . '/imagick;';
00674             }
00675             if ($bearsamppBins->getNodejs() && $bearsamppBins->getNodejs()->isEnable()) {
00676                 $paths .= self::getModuleSymlinkPath($bearsamppBins->getNodejs()) . ';';
00677             }
00678         }
00679 
00680         // Add paths for enabled tools
00681         if (isset($bearsamppTools)) {
00682             if ($bearsamppTools->getComposer() && $bearsamppTools->getComposer()->isEnable()) {
00683                 $paths .= self::getModuleSymlinkPath($bearsamppTools->getComposer()) . ';';
00684                 $paths .= self::getModuleSymlinkPath($bearsamppTools->getComposer()) . '/vendor/bin;';
00685             }
00686             if ($bearsamppTools->getGhostscript() && $bearsamppTools->getGhostscript()->isEnable()) {
00687                 $paths .= self::getModuleSymlinkPath($bearsamppTools->getGhostscript()) . '/bin;';
00688             }
00689             if ($bearsamppTools->getGit() && $bearsamppTools->getGit()->isEnable()) {
00690                 $paths .= self::getModuleSymlinkPath($bearsamppTools->getGit()) . '/bin;';
00691             }
00692             if ($bearsamppTools->getNgrok() && $bearsamppTools->getNgrok()->isEnable()) {
00693                 $paths .= self::getModuleSymlinkPath($bearsamppTools->getNgrok()) . ';';
00694             }
00695             if ($bearsamppTools->getPerl() && $bearsamppTools->getPerl()->isEnable()) {
00696                 $paths .= self::getModuleSymlinkPath($bearsamppTools->getPerl()) . '/perl/site/bin;';
00697                 $paths .= self::getModuleSymlinkPath($bearsamppTools->getPerl()) . '/perl/bin;';
00698                 $paths .= self::getModuleSymlinkPath($bearsamppTools->getPerl()) . '/c/bin;';
00699             }
00700             if ($bearsamppTools->getPython() && $bearsamppTools->getPython()->isEnable()) {
00701                 $paths .= self::getModuleSymlinkPath($bearsamppTools->getPython()) . '/bin;';
00702             }
00703             if ($bearsamppTools->getRuby() && $bearsamppTools->getRuby()->isEnable()) {
00704                 $paths .= self::getModuleSymlinkPath($bearsamppTools->getRuby()) . '/bin;';
00705             }
00706         }
00707 
00708         return self::formatWindowsPath($paths);
00709     }
